<?php
declare(strict_types=1);
$r=dirname(__DIR__);require_once $r.'/app/foundation.php';require_once $r.'/company/admin/core/functions.php';require_once $r.'/company/admin/modules/accounting-finance/functions.php';require_once $r.'/company/admin/modules/accounting-finance/core.php';require_once $r.'/company/admin/modules/accounting-finance/ledger.php';require_once $r.'/company/admin/modules/accounting-finance/invoices.php';require_once $r.'/company/admin/modules/accounting-finance/payments.php';require_once $r.'/company/admin/modules/accounting-finance/banking.php';
function bank_assert(bool $v,string $m):void{if(!$v)throw new RuntimeException($m);} yovel_admin_accounting_finance_schema();yovel_admin_finance_core_schema();yovel_admin_finance_payment_schema();yovel_admin_finance_banking_schema();$db=bx_db();$f=$db->GetRow("SELECT c.company_key,c.company_key_hash,c.company_name,a.admin_key FROM project_company c JOIN project_company_admin a ON a.company_key_hash=c.company_key_hash AND a.admin_status='ACTIVE' LIMIT 1");$c=['company_key'=>$f['company_key'],'company_key_hash'=>$f['company_key_hash'],'company_name'=>$f['company_name']];$a=['admin_key'=>$f['admin_key']];$s=strtoupper(substr(str_replace('-','',bx_uuid()),0,8));$acct=bx_uuid();$bank=bx_uuid();$pay=bx_uuid();
$db->Execute("INSERT INTO project_company_accounting_account(account_key,company_key,company_key_hash,account_code,account_name,root_type,report_type,account_type,account_currency,is_group,balance_must_be,account_status,created_by_admin_key,updated_by_admin_key) VALUES(?,?,?,?,?,'ASSET','BALANCE_SHEET','Bank','PHP',0,'EITHER','ACTIVE',?,?)",[$acct,$c['company_key'],$c['company_key_hash'],'BR_'.$s,'Bank Recon '.$s,$a['admin_key'],$a['admin_key']]);$db->Execute("INSERT INTO project_company_finance_bank_account(bank_account_key,company_key,company_key_hash,bank_account_code,bank_name,account_name,ledger_account_key,currency,status,created_by_admin_key,updated_by_admin_key) VALUES(?,?,?,?,?,?,?,'PHP','ACTIVE',?,?)",[$bank,$c['company_key'],$c['company_key_hash'],'BA_'.$s,'Test Bank','Operating',$acct,$a['admin_key'],$a['admin_key']]);$db->Execute("INSERT INTO project_company_finance_payment_entry(payment_entry_key,company_key,company_key_hash,payment_no,payment_type,posting_date,party_type,paid_to_account_key,paid_amount,received_amount,currency,exchange_rate,allocated_amount,unallocated_amount,document_status,created_by_admin_key,updated_by_admin_key) VALUES(?,?,?,?, 'RECEIVE','2026-07-02','NONE',?,1000,1000,'PHP',1,0,1000,'SUBMITTED',?,?)",[$pay,$c['company_key'],$c['company_key_hash'],'REC-'.$s,$acct,$a['admin_key'],$a['admin_key']]);
try{$csv="Date,Reference,Description,Deposit,Withdrawal\n2026-07-02,REC-$s,Customer receipt,1000,0\n2026-07-03,FEE-$s,Bank fee,0,25\n";$import=yovel_admin_import_bank_statement($db,$c,$a,$bank,$csv,['date'=>'Date','reference'=>'Reference','description'=>'Description','deposit'=>'Deposit','withdrawal'=>'Withdrawal']);bank_assert($import['imported_count']===2,'Bank import failed.');$again=yovel_admin_import_bank_statement($db,$c,$a,$bank,$csv,['date'=>'Date','reference'=>'Reference','description'=>'Description','deposit'=>'Deposit','withdrawal'=>'Withdrawal']);bank_assert($again['duplicate_count']===2,'Duplicate bank rows were not rejected.');$rows=yovel_admin_bank_statement_rows($c,$bank);$receipt=array_values(array_filter($rows,fn($x)=>(string)$x['reference_no']==='REC-'.$s))[0];$candidates=yovel_admin_bank_match_candidates($c,$receipt['bank_statement_row_key']);bank_assert($candidates&&$candidates[0]['source_record_key']===$pay,'Bank match ranking failed.');$match=yovel_admin_reconcile_bank_rows($db,$c,$a,[$receipt['bank_statement_row_key']],[['source_type'=>'PAYMENT_ENTRY','source_record_key'=>$pay,'matched_amount'=>'1000']]);bank_assert($match['status']==='RECONCILED','Bank reconcile failed.');yovel_admin_unreconcile_bank_match($db,$c,$a,$match['reconciliation_key'],'Fixture correction');$row=yovel_admin_bank_statement_rows($c,$bank)[0];bank_assert(in_array($row['reconciliation_status'],['UNRECONCILED','RECONCILED'],true),'Unreconcile state invalid.');}finally{$h=$c['company_key_hash'];$db->Execute('DELETE FROM project_company_finance_bank_match WHERE company_key_hash=? AND bank_statement_row_key IN (SELECT bank_statement_row_key FROM project_company_finance_bank_statement_row WHERE company_key_hash=? AND bank_account_key=?)',[$h,$h,$bank]);$db->Execute('DELETE FROM project_company_finance_bank_reconciliation WHERE company_key_hash=? AND bank_account_key=?',[$h,$bank]);$db->Execute('DELETE FROM project_company_finance_bank_statement_row WHERE company_key_hash=? AND bank_account_key=?',[$h,$bank]);$db->Execute('DELETE FROM project_company_finance_payment_entry WHERE company_key_hash=? AND payment_entry_key=?',[$h,$pay]);$db->Execute('DELETE FROM project_company_finance_bank_account WHERE company_key_hash=? AND bank_account_key=?',[$h,$bank]);$db->Execute('DELETE FROM project_company_accounting_account WHERE company_key_hash=? AND account_key=?',[$h,$acct]);}echo "Accounting/Finance banking checks passed.\n";
